+import { expect, test } from 'bun:test';
+import { readTheme, toggleTheme } from './index';
+
+test('defaults to light when nothing is stored', () => {
+  expect(readTheme({ getItem: () => null })).toBe('light');
+});
+
+test('restores dark from storage', () => {
+  expect(readTheme({ getItem: () => 'dark' })).toBe('dark');
+});
+
+test('toggles in both directions', () => {
+  expect(toggleTheme('light')).toBe('dark');
+  expect(toggleTheme('dark')).toBe('light');
+});
